#include "Demos/MaterialRefreshSurfaceDemo.h"

#include <cstdio>
#include <fstream>

int main(){using namespace NeoEngine;const char* output="/tmp/fauzanengine_material_refresh_surface_demo_smoke.ppm";MaterialRefreshSurfaceDemoConfig invalid{};invalid.frames=1U;MaterialRefreshSurfaceDemoReceipt receipt{};MaterialRefreshSurfaceDemoError error{};if(RunMaterialRefreshSurfaceDemo(invalid,receipt,error)||error!=MaterialRefreshSurfaceDemoError::InvalidConfiguration)return 1;MaterialRefreshSurfaceDemoConfig config{};config.width=96U;config.height=64U;config.frames=2U;config.hiddenSurface=true;config.ppmPath=output;if(!RunMaterialRefreshSurfaceDemo(config,receipt,error)||receipt.renderedFrames!=2U||receipt.presentedFrames!=2U||receipt.visiblePixels==0U||receipt.beforeFrameHash==0U||receipt.afterFrameHash==0U||receipt.beforeFrameHash==receipt.afterFrameHash||receipt.beforeMaterialHash==receipt.afterMaterialHash||receipt.beforeRgba==receipt.afterRgba)return 1;std::ifstream artifact(output,std::ios::binary);char header[2]{};if(!artifact.read(header,2)||header[0]!='P'||header[1]!='6')return 1;artifact.close();std::remove(output);std::printf("MATERIAL_REFRESH_SURFACE_DEMO_SMOKE_OK frames=%u before=%llu after=%llu rgba=%08X>%08X\n",receipt.renderedFrames,static_cast<unsigned long long>(receipt.beforeFrameHash),static_cast<unsigned long long>(receipt.afterFrameHash),receipt.beforeRgba,receipt.afterRgba);return 0;}
